        'قبل ما تفكّر بهالاتجاه — اسأل شركتك عن الخلية البيتية. أرخص، قانوني، وبيشتغل أحسن.',
        'إذا كنت مصمّم، تأكّد من وزارة الاتصالات ومن شركتك قبل ما تشتري أي إشي.'
