        ['ركبوا موجة الهجين بالشحن بالوقت الصحّ', 'حصة الـPHEV قفزت من 6.1٪ لـ23.8٪ بسنة وحدة. الصينيين كانوا جاهزين بموديلات PHEV بأسعار تنافسية لمّا صارت الضريبة على الكهربائي الكامل أثقل. توقيت ممتاز — أو حظّ ممتاز.'],
        ['كفالات طويلة', 'سبع سنين للسيارة وتمانية للبطارية صارت عادية عند علامات صينية. هاد بيهدّي بال المشتري المتردّد.'],
        ['مستوردين كبار وقفوا وراهم', 'مش مستورد صغير بمرآب — كلموبيل وكرسو وشلومو وديلك. لمّا شركة بحجم كلموبيل بتاخد علامة، الناس بتصدّق.']
