    dek: 'صاحبتي عندها Galaxy S26 Ultra وبتشتكي دايماً من وزنه وحجمه بجيبها. جرّبت Galaxy S26 العادي — وزن 167 جرام بس، شاشة 6.3 إنش مريحة بإيد واحدة، وتلسكوب 3× بصري ومقاومة IP68 كاملة. هل التنازلات تستاهل الفرق بالسعر؟ هون التفاصيل الموثّقة.',
