      ['«قطع الغيار مش متوفّرة وبتستنّى شهور»', 'كان هاد صحيح بالسنوات الأولى. اليوم مع هالحجم من المبيعات صار في مخزون محلّي ومراكز خدمة، بس التغطية الجغرافية مش متساوية.'],
      ['«كلّها نفس الشي — نفس المصنع ونفس السيارة باسم تاني»', 'في مجموعات صينية بتبيع تحت أكتر من علامة، بس الموديلات مش متطابقة.'],
      ['«رخيصة يعني مصنوعة على السريع»', 'السعر الأوطى مصدره سلسلة إنتاج وتوريد أرخص وهوامش ربح أقلّ — مش بالضرورة مواد أسوأ.']
